final class Schema{
 public static function register_tables():void{foreach(array('settings'=>self::settings_schema(),'analytics'=>self::analytics_schema(),'logs'=>self::logs_schema(),'projects'=>self::projects_schema(),'project_term_relationships'=>self::project_term_relationships_schema(),'teams'=>self::teams_schema(),'team_members'=>self::team_members_schema(),'project_teams'=>self::project_teams_schema(),'project_fields'=>self::project_fields_schema(),'project_field_values'=>self::project_field_values_schema(),'workspaces'=>self::workspaces_schema(),'project_relationships'=>self::project_relationships_schema(),'activity'=>self::activity_schema(),'tasks'=>self::tasks_schema(),'milestones'=>self::milestones_schema(),'requirements'=>self::requirements_schema(),'features'=>self::features_schema(),'user_stories'=>self::user_stories_schema(),'risks'=>self::governance_schema(),'issues'=>self::governance_schema(),'dependencies'=>self::governance_schema(),'decisions'=>self::governance_schema(),'bugs'=>self::quality_schema(),'test_cases'=>self::quality_schema(),'discussions'=>self::content_schema(),'notes'=>self::content_schema(),'files'=>self::files_schema(),'project_settings'=>self::project_settings_schema())as$name=>$schema)self::register($name,$schema);}
