 private static function projects_schema():string{return"id bigint(20) unsigned NOT NULL AUTO_INCREMENT,project_name varchar(191) NOT NULL,project_slug varchar(191) NOT NULL,project_key varchar(32) NOT NULL,project_description longtext DEFAULT NULL,parent_id bigint(20) unsigned DEFAULT NULL,owner_id bigint(20) unsigned DEFAULT NULL,status varchar(32) NOT NULL DEFAULT 'planning',priority varchar(32) NOT NULL DEFAULT 'normal',visibility varchar(32) NOT NULL DEFAULT 'private',start_date datetime DEFAULT NULL,target_end_date datetime DEFAULT NULL,actual_end_date datetime DEFAULT NULL,created_by bigint(20) unsigned DEFAULT NULL,created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by bigint(20) unsigned DEFAULT NULL,updated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (id),UNIQUE KEY project_key (project_key),UNIQUE KEY project_slug (project_slug),KEY parent_id (parent_id),KEY owner_id (owner_id),KEY status (status),KEY priority (priority),KEY visibility (visibility),KEY updated_at (updated_at)";}
